/* Nonomura Hospital - native Nintendo 3DS frontend.
 * Runs the original (Korean-patched) DOS game on a built-in x86 emulator.
 * Top screen: the game picture (640x480 box-filtered to 320x240). Bottom screen: the dialogue text, re-laid out in large type. */
#include <3ds.h>
#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#include "../../core/machine.h"
#include "../../core/textcap.h"
#include "vgascale.h"
#include "font8x8.h"
#include "kfont.h"
#include "frameshape.h"          /* generated by tools/gen_kfont.py: the Korean UI font */

u32 __stacksize__ = 0x40000;

#define APP_VERSION "0.1"
#define TICKS_PER_SEC ((u64)SYSCLOCK_ARM11)
#define FRAME_TICKS (TICKS_PER_SEC / 60)
#define C565(r, g, b) ((uint16_t)((((r) >> 3) << 11) | (((g) >> 2) << 5) | ((b) >> 3)))

/* ------------------------------------------------------------------ config */
#ifndef GAME_DIR0
#define GAME_DIR0 "sdmc:/3ds/nonomura"
#endif
static const char *GAME_DIRS[] = { GAME_DIR0, "sdmc:/nonomura", NULL };
#define IPS_MIN 1200000u
#define IPS_MAX 4000000u      /* Auto never runs the emulated CPU faster than the nominal speed: iteration-based delay loops would speed the game up */
static const uint32_t CPU_FIXED[] = { 0, 2000000, 3000000, 4000000, 5000000, 6000000 };   /* 0 = auto */
#define N_CPU_MODES 6
static int cpu_mode = 0, mouse_level = 3;
static int win_hide = 1;              /* 1: while the engine's message window is up, the top screen shows only the picture (the text is on the bottom screen) */
static int win_state, win_cand, win_cnt, win_force;   /* current view, candidate view, frames the candidate has held, redraw request */
static int pic_mode = PIC_FILL;       /* picture-only top view: PIC_FILL / PIC_STRETCH / PIC_FIT */
static int top_zoom = 1;              /* 1: 640x400 game area stretched over the whole top screen, 0: original 4:3 picture */
static int s3d_mode = 0;              /* 3D style: 0 characters and the picture frame stand out in front of the flat background, 1 whole picture (tilt + frame), 2 characters only */
static int s3d_level = 2;             /* top screen stereoscopic 3D: 0 off, 1 weak, 2 medium, 3 strong (the 3D slider scales it further) */
static int text_size = 1;             /* bottom-screen text: 0 large, 1 medium, 2 small, 3 tiny */
static const float TEXT_SCALE[] = { 2.0f, 1.5f, 1.25f, 1.0f };
static const char *TEXT_NAME[] = { "크게", "보통", "작게", "아주 작게" };
static char cfg_path[320];
static void cfg_save(void) {
    FILE *f = fopen(cfg_path, "w"); if (!f) return;
    fprintf(f, "cpu_mode=%d\nmouse_level=%d\ntop_zoom=%d\ntext_size=%d\nwin_hide=%d\npic_mode=%d\ns3d=%d\ns3dm=%d\n", cpu_mode, mouse_level, top_zoom, text_size, win_hide, pic_mode, s3d_level, s3d_mode);
    fclose(f);
}
static void cfg_load(void) {
    FILE *f = fopen(cfg_path, "r"); if (!f) return;
    char line[64]; int v;
    while (fgets(line, sizeof line, f)) {
        if (sscanf(line, "cpu_mode=%d", &v) == 1 && v >= 0 && v < 6) cpu_mode = v;
        else if (sscanf(line, "mouse_level=%d", &v) == 1 && v >= 1 && v <= 5) mouse_level = v;
        else if (sscanf(line, "top_zoom=%d", &v) == 1) top_zoom = v ? 1 : 0;
        else if (sscanf(line, "win_hide=%d", &v) == 1) win_hide = v ? 1 : 0;
        else if (sscanf(line, "pic_mode=%d", &v) == 1 && v >= 0 && v < 3) pic_mode = v;
        else if (sscanf(line, "text_size=%d", &v) == 1 && v >= 0 && v < 4) text_size = v;
        else if (sscanf(line, "s3d=%d", &v) == 1 && v >= 0 && v < 4) s3d_level = v;
        else if (sscanf(line, "s3dm=%d", &v) == 1 && v >= 0 && v < 3) s3d_mode = v;
    }
    fclose(f);
}
static const float MOUSE_SPEED[] = { 0, 5.f, 8.f, 11.f, 15.f, 20.f };   /* pixels per frame at full circle-pad deflection */

/* ------------------------------------------------------------------ log */
static FILE *logfp;
static u64 t_start;
static void LOG(const char *fmt, ...) {
    if (!logfp) return;
    va_list ap; va_start(ap, fmt);
    double t = (double)(svcGetSystemTick() - t_start) / TICKS_PER_SEC;
    fprintf(logfp, "[%6.1f] ", t);
    vfprintf(logfp, fmt, ap); fputc('\n', logfp);
    if (t < 60.0) fflush(logfp);          /* later lines stay in the buffer: a flush to the SD card can stall the frame loop (and the music) */
    va_end(ap);
}

/* ------------------------------------------------------------------ tiny drawing helpers (column-major RGB565) */
static uint16_t *fbTop, *fbTopR, *fbBot;      /* fbTopR: right-eye image (only distinct from fbTop while the top screen is in 3D mode) */
static void fb_get(void) {
    u16 w, h;
    fbTop = (uint16_t *)gfxGetFramebuffer(GFX_TOP, GFX_LEFT, &w, &h);
    fbTopR = (uint16_t *)gfxGetFramebuffer(GFX_TOP, GFX_RIGHT, &w, &h);
    fbBot = (uint16_t *)gfxGetFramebuffer(GFX_BOTTOM, GFX_LEFT, &w, &h);
}
static void fill(uint16_t *fb, int fbw, uint16_t c) { for (int i = 0; i < fbw * 240; i++) fb[i] = c; }
static void gputc(uint16_t *fb, int fbw, int x, int y, int ch, uint16_t fg, int bg, int sc) {
    const unsigned char *g = &font8x8[(ch & 255) * 8];
    for (int r = 0; r < 8; r++)
        for (int c = 0; c < 8; c++) {
            int on = g[r] & (0x80 >> c);
            if (!on && bg < 0) continue;
            uint16_t col = on ? fg : (uint16_t)bg;
            for (int sy = 0; sy < sc; sy++)
                for (int sx = 0; sx < sc; sx++) {
                    int px = x + c * sc + sx, py = y + r * sc + sy;
                    if (px < 0 || px >= fbw || py < 0 || py >= 240) continue;
                    fb[px * 240 + (239 - py)] = col;
                }
        }
}
/* draws s with '\n' support and word-agnostic wrapping at maxcols; returns the y after the last line */
static int gtext(uint16_t *fb, int fbw, int x, int y, int maxcols, const char *s, uint16_t fg, int bg, int sc) {
    int col = 0, x0 = x;
    for (; *s; s++) {
        if (*s == '\n' || col >= maxcols) { x = x0; y += 8 * sc + 2; col = 0; if (*s == '\n') continue; }
        gputc(fb, fbw, x, y, (unsigned char)*s, fg, bg, sc); x += 8 * sc; col++;
    }
    return y + 8 * sc + 2;
}
static void present(void) { gfxFlushBuffers(); gfxSwapBuffers(); gspWaitForVBlank(); }

/* ---- Korean UI text: UTF-8 strings drawn with the generated anti-aliased font (kfont.h) over a flat background ---- */
#define KF_LH (KF_H - 1)
static void frect(uint16_t *fb, int fbw, int x, int y, int w, int h, uint16_t c) {
    for (int px = x < 0 ? 0 : x; px < x + w && px < fbw; px++)
        for (int py = y < 0 ? 0 : y; py < y + h && py < 240; py++) fb[px * 240 + (239 - py)] = c;
}
static int kf_find(uint32_t cp) {
    int lo = 0, hi = KF_N - 1;
    while (lo <= hi) { int mid = (lo + hi) / 2; if (kf_cp[mid] == cp) return mid; if (kf_cp[mid] < cp) lo = mid + 1; else hi = mid - 1; }
    return -1;
}
static uint32_t u8next(const char **ps) {      /* never reads past the terminator; bytes that are not valid UTF-8 come out as '?' */
    const unsigned char *p = (const unsigned char *)*ps; uint32_t c = *p++;
    int n = c >= 0xF0 ? 3 : c >= 0xE0 ? 2 : c >= 0xC0 ? 1 : 0;
    if (c >= 0x80 && !n) c = '?';
    else if (n) {
        int k = 0; while (k < n && (p[k] & 0xC0) == 0x80) k++;
        if (k < n) c = '?';
        else { c &= 0x3F >> n; for (k = 0; k < n; k++) c = (c << 6) | (p[k] & 63); }
        p += k;
    }
    *ps = (const char *)p; return c;
}
static int kglyph_adv(uint32_t cp) { int g = kf_find(cp); if (g < 0) g = kf_find('?'); return g < 0 ? KF_H / 2 : kf_adv[g]; }
static int kwidth(const char *s) {          /* width of the first line */
    int w = 0; while (*s && *s != '\n') w += kglyph_adv(u8next(&s)); return w;
}
static void kglyph_draw(uint16_t *fb, int fbw, int x, int y, uint32_t cp, uint16_t fg) {
    int g = kf_find(cp); if (g < 0) g = kf_find('?'); if (g < 0) return;
    int adv = kf_adv[g]; const uint8_t *d = kf_data + kf_off[g];
    int fr = (fg >> 11) & 31, fgc = (fg >> 5) & 63, fb5 = fg & 31;
    for (int r = 0; r < KF_H; r++)
        for (int c = 0; c < adv; c++) {
            int i = r * adv + c, a = (i & 1) ? (d[i >> 1] & 15) : (d[i >> 1] >> 4);
            if (!a) continue;
            int px = x + c, py = y + r; if (px < 0 || px >= fbw || py < 0 || py >= 240) continue;
            uint16_t *q = &fb[px * 240 + (239 - py)]; uint16_t o = *q;
            int or_ = (o >> 11) & 31, og = (o >> 5) & 63, ob = o & 31, A = a * 17;
            int nr = or_ + ((fr - or_) * A) / 255, ng = og + ((fgc - og) * A) / 255, nb = ob + ((fb5 - ob) * A) / 255;
            *q = (uint16_t)((nr << 11) | (ng << 5) | nb);
        }
}
/* '\n' starts a new line; text that would pass x+maxw wraps.  bold: each glyph drawn twice, one pixel apart.  Returns the y below the last line. */
static int ktext(uint16_t *fb, int fbw, int x, int y, int maxw, const char *s, uint16_t fg, int bold) {
    int x0 = x;
    while (*s) {
        uint32_t cp = u8next(&s);
        if (cp == '\n') { x = x0; y += KF_LH; continue; }
        int adv = kglyph_adv(cp);
        if (x > x0 && x + adv > x0 + maxw) { x = x0; y += KF_LH; if (cp == ' ') continue; }
        kglyph_draw(fb, fbw, x, y, cp, fg);
        if (bold) kglyph_draw(fb, fbw, x + 1, y, cp, fg);
        x += adv + (bold ? 1 : 0);
    }
    return y + KF_LH;
}

/* message screen on both displays; waits for START (or B) */
static void message_screen(const char *title, const char *body) {
    while (aptMainLoop()) {
        fb_get();
        fill(fbTop, 400, C565(10, 10, 30));
        ktext(fbTop, 400, 10, 10, 380, title, C565(255, 220, 80), 1);
        fill(fbBot, 320, C565(10, 10, 30));
        ktext(fbBot, 320, 8, 8, 304, body, C565(230, 230, 230), 0);
        ktext(fbBot, 320, 8, 240 - KF_LH - 4, 304, "START 버튼을 누르면 종료합니다", C565(150, 200, 255), 0);
        present();
        hidScanInput();
        if (hidKeysDown() & (KEY_START | KEY_B)) break;
    }
}

/* ------------------------------------------------------------------ audio */
#ifndef NDSP_SAMPLE_RATE
#define NDSP_SAMPLE_RATE 32728.498          /* the DSP's own rate: playing at exactly this rate needs no resampling on the DSP side */
#endif
#define AUD_RATE 32728                       /* synth output rate (integer; the DSP consumes 0.0015% faster, which the pump absorbs) */
#define NWB 96                               /* wave buffer slots: 96 x (one frame of sound, ~550 samples) holds ~1.6 s, more than LEAD_MAX */
#define AFRAMES 1024
/* The emulation runs LEAD_S ahead of real time, so that much sound is always queued at the DSP.  A frame that takes
 * long (SD card access, a big redraw, a save) then only eats into that reserve instead of making the music stop. */
#define LEAD_S 0.40
#define LEAD_MAX 0.90
/* The reserve grows by 0.1 s whenever the music still ran dry (this device stalls longer than the reserve) and shrinks slowly while all is calm. */
static double lead_s = LEAD_S;
#define START_FRAMES (AUD_RATE * 15 / 100)  /* playback (re)starts once this much is queued */
static unsigned aud_underruns, aud_dropped;
static ndspWaveBuf wbuf[NWB];
static int16_t *abuf;
static int audio_ok;
static void audio_init(void) {
    if (R_FAILED(ndspInit())) { LOG("ndspInit failed (dspfirm.cdc missing?) - no audio"); return; }
    abuf = linearAlloc((size_t)NWB * AFRAMES * 4);
    if (!abuf) { ndspExit(); return; }
    ndspSetOutputMode(NDSP_OUTPUT_STEREO);
    ndspChnReset(0);
    ndspChnSetInterp(0, NDSP_INTERP_LINEAR);
    ndspChnSetRate(0, (float)NDSP_SAMPLE_RATE);
    ndspChnSetFormat(0, NDSP_FORMAT_STEREO_PCM16);
    float mix[12] = { 0 }; mix[0] = mix[1] = 1.0f;
    ndspChnSetMix(0, mix);
    ndspChnSetPaused(0, true);
    memset(wbuf, 0, sizeof wbuf);
    for (int i = 0; i < NWB; i++) wbuf[i].data_pcm16 = abuf + (size_t)i * AFRAMES * 2;
    audio_ok = 1;
}
static int audio_started;
static float audio_rate = (float)NDSP_SAMPLE_RATE;
static int audio_queued(void) {
    int n = 0;
    for (int i = 0; i < NWB; i++) if (wbuf[i].status == NDSP_WBUF_QUEUED || wbuf[i].status == NDSP_WBUF_PLAYING) n++;
    return n;
}
static uint32_t audio_queued_frames(void) {
    uint32_t n = 0;
    for (int i = 0; i < NWB; i++) if (wbuf[i].status == NDSP_WBUF_QUEUED || wbuf[i].status == NDSP_WBUF_PLAYING) n += wbuf[i].nsamples;
    return n;
}
/* Only a machine that is chronically slower than real time gets its sound slowed down to match (short dips are
 * absorbed by the queued reserve; changing the pitch for them would itself sound broken). */
static void audio_set_speed(double ratio) {
    if (!audio_ok) return;
    /* A slow second is almost always a one-off stall; slowing the DSP for it bends the pitch and lets the queue grow for good.
     * Only a slowness that lasts several seconds in a row is followed. */
    static int slow_secs;
    if (ratio < 0.9) slow_secs++; else if (ratio >= 0.97) slow_secs = 0;
    if (slow_secs < 4) ratio = 1.0;
    if (ratio > 1.0) ratio = 1.0;
    if (ratio < 0.5) ratio = 0.5;
    float r = ratio >= 0.93 ? (float)NDSP_SAMPLE_RATE : (float)(NDSP_SAMPLE_RATE * ratio);
    if (r != audio_rate) { audio_rate = r; ndspChnSetRate(0, r); }
}
static double now_ms(void) { return (double)svcGetSystemTick() * 1000.0 / TICKS_PER_SEC; }
static void audio_pump(Machine *m) {
    opl_sync(m->opl);
    uint32_t n = opl_available(m->opl);
    if (!audio_ok) { opl_discard(m->opl, n); return; }
    /* the DSP ran completely dry since the last frame: stop, and wait until a reserve has been rebuilt */
    if (audio_started && audio_queued() == 0) { ndspChnSetPaused(0, true); audio_started = 0; aud_underruns++; lead_s += 0.10; if (lead_s > LEAD_MAX) lead_s = LEAD_MAX; }
    /* never throw samples away just because every buffer is busy: they wait in the synth ring (2 s) for the next frame.
     * Only an absurd backlog is trimmed (keeping the newest 0.4 s). */
    if (n > AUD_RATE * 17 / 10) { opl_discard(m->opl, n - AUD_RATE * 4 / 10); n = AUD_RATE * 4 / 10; aud_dropped++; }
    while (n) {
        ndspWaveBuf *wb = NULL;
        for (int i = 0; i < NWB; i++)
            if (wbuf[i].status == NDSP_WBUF_FREE || wbuf[i].status == NDSP_WBUF_DONE) { wb = &wbuf[i]; break; }
        if (!wb) break;
        uint32_t c = n > AFRAMES ? AFRAMES : n;
        opl_mix(m->opl, wb->data_pcm16, c);
        DSP_FlushDataCache(wb->data_pcm16, c * 4);
        wb->nsamples = c;
        ndspChnWaveBufAdd(0, wb);
        n -= c;
    }
    if (!audio_started && audio_queued_frames() >= START_FRAMES) { ndspChnSetPaused(0, false); audio_started = 1; }
}
/* the pause menu does not run the emulator: let the queue play out silently and start clean afterwards */
static void audio_hold(void) {
    if (!audio_ok) return;
    ndspChnSetPaused(0, true); audio_started = 0;
}
/* Sound test (pause menu): a clean tone sequence straight through the same DSP path, independent of the emulation.
 * Clean here but distorted in the game = the problem is in the emulated music, not in the 3DS audio output. */
static void audio_test(void) {
    if (!audio_ok) return;
    u64 t0 = svcGetSystemTick();
    ndspChnSetPaused(0, false); audio_started = 0;                       /* let whatever is still queued play out first */
    while (audio_queued() && svcGetSystemTick() - t0 < TICKS_PER_SEC) gspWaitForVBlank();
    ndspChnSetPaused(0, true);
    static const float notes[] = { 261.63f, 329.63f, 392.00f, 523.25f, 392.00f, 329.63f, 261.63f };
    const int per = AUD_RATE * 4 / 10;                                   /* 0.4 s per note */
    double ph = 0; int idx = 0, left = per, nn = (int)(sizeof notes / sizeof notes[0]), bi = 0, queued = 0;
    while (idx < nn) {
        ndspWaveBuf *wb = &wbuf[bi % NWB];
        u64 w0 = svcGetSystemTick();
        while ((wb->status == NDSP_WBUF_QUEUED || wb->status == NDSP_WBUF_PLAYING) && svcGetSystemTick() - w0 < TICKS_PER_SEC) gspWaitForVBlank();
        int c = left < AFRAMES ? left : AFRAMES;
        for (int i = 0; i < c; i++) {
            float env = 1.0f; int pos = per - left + i;
            if (pos < 1500) env = pos / 1500.0f;
            if (per - pos < 1500) env = (per - pos) / 1500.0f;
            int16_t v = (int16_t)(sinf((float)ph) * 9000.0f * env);
            ph += 2.0 * 3.14159265358979 * notes[idx] / AUD_RATE;
            wb->data_pcm16[i * 2] = wb->data_pcm16[i * 2 + 1] = v;
        }
        if (ph > 1e6) ph = fmod(ph, 2.0 * 3.14159265358979);
        DSP_FlushDataCache(wb->data_pcm16, (u32)c * 4);
        wb->nsamples = c; ndspChnWaveBufAdd(0, wb); bi++; queued++;
        if (queued == 3) ndspChnSetPaused(0, false);
        left -= c; if (left <= 0) { idx++; left = per; ph = 0; }
    }
    t0 = svcGetSystemTick();
    while (audio_queued() && svcGetSystemTick() - t0 < 4 * TICKS_PER_SEC) gspWaitForVBlank();
    ndspChnSetPaused(0, true); audio_started = 0;
}

/* ------------------------------------------------------------------ input */
typedef struct { uint32_t key; uint8_t sc; uint8_t ascii; } KeyMap;
static const KeyMap KEYS[] = {
    { KEY_DUP, 0x48, 0 }, { KEY_DDOWN, 0x50, 0 }, { KEY_DLEFT, 0x4B, 0 }, { KEY_DRIGHT, 0x4D, 0 },
    { KEY_X, 0x1C, 13 },  /* Enter */
    { KEY_Y, 0x01, 27 },  /* Esc */
    { KEY_L, 0x1D, 0 },   /* Ctrl */
    { KEY_R, 0x39, ' ' }, /* Space */
};
static uint32_t prev_held;
static int key_age[sizeof KEYS / sizeof KEYS[0]];      /* frames since the key went down (-1: up) */
static uint32_t key_sent;                               /* bit i: key i is currently down in the emulated keyboard */
static float mx_acc, my_acc;
static int lb_frames, rb_frames;          /* remaining frames a click is held (min press length) */
static int touch_active, touch_x0, touch_y0, touch_lx, touch_ly, touch_age, touch_moved;

static void mouse_move(Machine *m, float dx, float dy) {
    mx_acc += dx; my_acc += dy;
    int ix = (int)mx_acc, iy = (int)my_acc;
    mx_acc -= ix; my_acc -= iy;
    m->mouse_x += ix; m->mouse_y += iy;
    if (m->mouse_x < m->mouse_minx) m->mouse_x = m->mouse_minx;
    if (m->mouse_x > m->mouse_maxx) m->mouse_x = m->mouse_maxx;
    if (m->mouse_y < m->mouse_miny) m->mouse_y = m->mouse_miny;
    if (m->mouse_y > m->mouse_maxy) m->mouse_y = m->mouse_maxy;
}

static void input_frame(Machine *m) {
    uint32_t held = hidKeysHeld();
    /* keyboard keys: press edges immediately; releases only after >= 4 frames so the game's tick-rate polling never misses a tap */
    for (unsigned i = 0; i < sizeof KEYS / sizeof KEYS[0]; i++) {
        uint32_t k = KEYS[i].key; uint32_t bit = 1u << i;
        if (key_sent & bit) key_age[i]++;
        if (held & k) {
            if (!(key_sent & bit)) { machine_key(m, KEYS[i].sc, 1, KEYS[i].ascii); key_sent |= bit; key_age[i] = 0; }
        } else if ((key_sent & bit) && key_age[i] >= 4) {
            machine_key(m, KEYS[i].sc, 0, KEYS[i].ascii); key_sent &= ~bit;
        }
    }
    /* mouse buttons with a minimum press length so a quick tap is never missed by the game's polling */
    if ((held & KEY_A) && !(prev_held & KEY_A)) lb_frames = 3;
    if ((held & KEY_B) && !(prev_held & KEY_B)) rb_frames = 3;
    /* circle pad -> mouse */
    circlePosition cp; hidCircleRead(&cp);
    float sp = MOUSE_SPEED[mouse_level];
    if (held & KEY_ZL) sp *= 0.3f;
    if (held & KEY_ZR) sp *= 2.0f;
    const float DZ = 16.f, MAXC = 150.f;
    float ax = (float)cp.dx, ay = (float)cp.dy;
    float mag = sqrtf(ax * ax + ay * ay);
    if (mag > DZ) {
        float n = (mag - DZ) / (MAXC - DZ); if (n > 1.f) n = 1.f;
        float v = (0.5f * n * n + 0.5f * n) * sp;
        mouse_move(m, ax / mag * v, -ay / mag * v);
    }
    /* touch screen = trackpad (drag moves, short tap clicks) */
    int left_touch = 0;
    if (held & KEY_TOUCH) {
        touchPosition tp; hidTouchRead(&tp);
        if (!touch_active) { touch_active = 1; touch_x0 = touch_lx = tp.px; touch_y0 = touch_ly = tp.py; touch_age = 0; touch_moved = 0; }
        else {
            mouse_move(m, (tp.px - touch_lx) * 2.0f, (tp.py - touch_ly) * 2.0f);
            touch_lx = tp.px; touch_ly = tp.py; touch_age++;
            if (abs(tp.px - touch_x0) + abs(tp.py - touch_y0) > 8) touch_moved = 1;
        }
    } else if (touch_active) {
        if (!touch_moved && touch_age < 15) left_touch = 1;
        touch_active = 0;
    }
    if (left_touch) lb_frames = 3;
    int btn = 0;
    if ((held & KEY_A) || lb_frames > 0) btn |= 1;
    if ((held & KEY_B) || rb_frames > 0) btn |= 2;
    if (lb_frames > 0) lb_frames--;
    if (rb_frames > 0) rb_frames--;
    m->mouse_btn = btn;
    prev_held = held;
}

static void input_release_all(Machine *m) {
    for (unsigned i = 0; i < sizeof KEYS / sizeof KEYS[0]; i++)
        if (key_sent & (1u << i)) machine_key(m, KEYS[i].sc, 0, KEYS[i].ascii);
    key_sent = 0; prev_held = 0; m->mouse_btn = 0; lb_frames = rb_frames = 0; touch_active = 0;
}

/* ------------------------------------------------------------------ rendering */
static uint16_t topimg[400 * 240];      /* last rendered game frame for the top screen (column-major, 400x240) */
static unsigned topimg_gen;             /* bumped whenever topimg changes (the eye images are rebuilt from it) */
static void char_layer(Machine *m);
static void top_render_to(Machine *m, uint16_t *dst) {
    if (win_hide && win_state) {                          /* message window up: picture only, the text lives on the bottom screen */
        if (top_zoom) vgascale_render_picture(m, dst, pic_mode);
        else {
            vgascale_render(m, dst, 40);
            for (int x = 0; x < 400; x++) memset(dst + x * 240, 0, 64 * sizeof(uint16_t));      /* picture rows 176..239 = the window strip */
        }
        return;
    }
    if (top_zoom) vgascale_render_zoom(m, dst);
    else vgascale_render(m, dst, 40);                     /* 320x240 picture centred in the 400-wide screen */
}
static int s3d_on, s3d_chars, s3d_frame;          /* top screen currently in 3D / and it is the "characters only" style */
static void top_render(Machine *m) {
    topimg_gen++;
    top_render_to(m, topimg);
    if (s3d_chars) char_layer(m);
}
/* once per frame: is the message window up?  The view only switches after the answer has been the same for a few
 * frames, so the picture does not jump while the engine redraws the window. */
static void win_update(Machine *m) {
    int up = win_hide && vgascale_window_up(m);
    if (up == win_cand) { if (win_cnt < 1000) win_cnt++; } else { win_cand = up; win_cnt = 0; }
    if (win_cand != win_state && win_cnt >= 6) { win_state = win_cand; win_force = 1; }
}
static void top_clear(void) { memset(topimg, 0, sizeof topimg); topimg_gen++; }

/* ---- top screen stereoscopic 3D ("tilt + pop-up frame"):
 * The finished 2D picture is turned into a left and a right image.  The picture is a sloped plane: its bottom edge sits at the
 * screen surface and its top edge recedes behind it (each row is shifted sideways, opposite ways in the two eyes), and a frame
 * around the picture floats in front of it.  The frame also hides the strips that the sideways shifts uncover at the edges.
 * The amount of depth follows the console's 3D slider and the menu setting (off / weak / medium / strong). */
#define S3D_TILT 10          /* total left/right offset (pixels) between the eyes at the top row at full strength */
#define S3D_CHAR_POP 12      /* "characters only" style: how far (pixels between the eyes) the characters stand out in front of the background at full strength */
#define S3D_FRAME_POP 5     /* the same for the picture frame (less than the characters) */
#define S3D_POP 4            /* the frame's offset towards the viewer at full strength */
static const char *S3D_NAME[] = { "끔", "약", "중", "강" };
static const float S3D_GAIN[] = { 0.f, 0.4f, 0.7f, 1.f };
static uint16_t eyeL[400 * 240], eyeR[400 * 240];
static unsigned eye_gen = ~0u, eye_cl;
static int eye_key = -1, s3d_tilt, s3d_pop, s3d_fpop;
static float s3d_slider;

/* once per frame, before the framebuffers are fetched: read the slider and switch the top screen between 2D and 3D */
static void s3d_update(void) {
    float sl = osGet3DSliderState();
    if (sl < 0.f) sl = 0.f; else if (sl > 1.f) sl = 1.f;
    s3d_slider = sl;
    float g = S3D_GAIN[s3d_level] * sl;
    if (s3d_mode != 1) { s3d_tilt = 0; s3d_pop = (int)(S3D_CHAR_POP * g + 0.5f); s3d_fpop = s3d_mode == 0 ? (int)(S3D_FRAME_POP * g + 0.5f) : 0; }
    else { s3d_tilt = (int)(S3D_TILT * g + 0.5f); s3d_pop = (int)(S3D_POP * g + 0.5f); s3d_fpop = 0; }
    int on = s3d_level > 0 && (s3d_tilt > 0 || s3d_pop > 0);
    if (on != s3d_on) { s3d_on = on; gfxSet3D(on); }
    s3d_chars = on && s3d_mode != 1; s3d_frame = on && s3d_mode == 0 && s3d_fpop > 0;
}
static void make_eye(uint16_t *dst, const uint16_t *src, int eye, int tilt, int pop, int B) {
    /* eye 0 = left, 1 = right.  Behind-the-screen points move left in the left image and right in the right image; points in front the other way round. */
    int j0[260], n[260], sh[260], nr = 0;
    for (int j = 0; j < 240; j++) {                                  /* j = memory index inside a column = 239 - y */
        int y = 239 - j, ci = (int)(tilt * (239 - y) / 239.0 + 0.5);   /* y = 0 (top) recedes by 'tilt', y = 239 (bottom) stays at the screen */
        int s = eye ? ci - ci / 2 : -(ci / 2);
        if (nr && sh[nr - 1] == s) n[nr - 1]++; else { j0[nr] = j; n[nr] = 1; sh[nr] = s; nr++; }
    }
    int fs = eye ? -(pop / 2) : pop - pop / 2;                         /* frame shift */
    uint16_t frm[16];
    for (int d = 0; d < B && d < 16; d++)
        frm[d] = d == B - 1 ? C565(200, 204, 220) : d == B - 2 ? C565(84, 90, 118) : d == 0 ? C565(8, 8, 14) : C565(18, 18, 30);
    for (int x = 0; x < 400; x++) {
        uint16_t *dc = dst + x * 240;
        for (int r = 0; r < nr; r++) {
            int sx = x - sh[r]; sx = sx < 0 ? 0 : sx > 399 ? 399 : sx;
            memcpy(dc + j0[r], src + sx * 240 + j0[r], n[r] * sizeof(uint16_t));
        }
        if (B <= 0) continue;
        int xf = x - fs, dx = xf < 399 - xf ? xf : 399 - xf;
        if (dx < B) {
            for (int j = 0; j < 240; j++) {
                int dy = j < 239 - j ? j : 239 - j, d = dx < dy ? dx : dy;
                if (d < B) dc[j] = frm[d < 0 ? 0 : d];
            }
        } else for (int j = 0; j < B; j++) dc[j] = dc[239 - j] = frm[j];
    }
}
/* ---- "characters only" 3D.  The engine draws the background with one routine and the characters with another (see vga_write), so the
 * emulator keeps a second copy of the screen without the characters (VGA.bgplane).  Rendering both copies the same way and comparing
 * them gives a character mask; the characters are then shifted sideways (in front of the screen) over the untouched, complete background. */
static uint16_t topbg[400 * 240];       /* the picture rendered from the background-only screen copy */
static uint8_t chmask[400 * 240], chtmp[400 * 240];
static unsigned cl_pic = ~0u, cl_pal = ~0u, cl_chr = ~0u, cl_key = ~0u, cl_top = ~0u, cl_ver;
static int cl_fr;
static int cl_cov;                      /* characters' share of the picture, in permille */
static int cl_strip;                    /* rows (counted from the bottom of the top image) that hold the message window and stay flat */
/* 5-tap dilate (dil=1) or erode along columns (step 1) or rows (step 240) */
static void morph5(uint8_t *dst, const uint8_t *src, int step, int along, int lines, int dil) {
    for (int a = 0; a < lines; a++)
        for (int i = 0; i < along; i++) {
            int hit = 0, all = 1;
            for (int k = -2; k <= 2; k++) {
                int q = i + k; int v = (q < 0 || q >= along) ? !dil : src[a * (step == 1 ? 240 : 1) + q * step];
                if (v) hit = 1; else all = 0;
            }
            dst[a * (step == 1 ? 240 : 1) + i * step] = dil ? hit : all;
        }
}
/* The picture frame (see frameshape.h): masks in top-image coordinates, made by rendering synthetic planes with the normal scaler. */
static uint8_t ringpl[4][0x10000], intpl[4][0x10000];
static uint8_t frmask[400 * 240], inmask[400 * 240];
static uint16_t ringtmp[400 * 240];
static uint16_t bgx[400 * 240];         /* topbg where the picture also continues under the inner part of the frame (what shows when the frame moves aside) */
static int frame_ready;
static unsigned fr_key = ~0u;
static void frame_planes(void) {
    for (int r = 0; r < FR_ROWS; r++)
        for (int x = 0; x < 640; x++) {
            int in = x >= FR_L[r] && x < FR_R[r] && r >= FR_T[x] && r < FR_B[x];
            uint8_t (*pl)[0x10000] = in ? intpl : ringpl;
            uint32_t off = (uint32_t)(FR_ROW0 + r) * 80 + (x >> 3); uint8_t bit = (uint8_t)(0x80 >> (x & 7));
            for (int k = 0; k < 4; k++) pl[k][off] |= bit;
        }
    frame_ready = 1;
}
static void frame_masks(Machine *m) {
    if (!frame_ready) frame_planes();
    const uint8_t *rp[4] = { ringpl[0], ringpl[1], ringpl[2], ringpl[3] }, *ip[4] = { intpl[0], intpl[1], intpl[2], intpl[3] };
    vgascale_set_planes(rp); top_render_to(m, ringtmp);
    for (int i = 0; i < 400 * 240; i++) frmask[i] = ((ringtmp[i] >> 5) & 63) > 31;
    vgascale_set_planes(ip); top_render_to(m, ringtmp);
    for (int i = 0; i < 400 * 240; i++) inmask[i] = ((ringtmp[i] >> 5) & 63) > 31;
    vgascale_set_planes(NULL);
}
#define FR_EXT 8
static void build_bgx(void) {
    memcpy(bgx, topbg, sizeof bgx);
    int lx[400], rx[400];
    for (int j = 0; j < 240; j++) {
        int last = -1000; for (int x = 0; x < 400; x++) { if (inmask[x * 240 + j]) last = x; lx[x] = last; }
        int next = 1000; for (int x = 399; x >= 0; x--) { if (inmask[x * 240 + j]) next = x; rx[x] = next; }
        for (int x = 0; x < 400; x++) {
            int i = x * 240 + j; if (!frmask[i]) continue;
            int dl = x - lx[x], dr = rx[x] - x;
            if (dl <= dr) { if (dl <= FR_EXT) bgx[i] = topbg[lx[x] * 240 + j]; }
            else if (dr <= FR_EXT) bgx[i] = topbg[rx[x] * 240 + j];
        }
    }
}
static void char_layer(Machine *m) {
    VGA *v = &m->vga;
    int strip = !(win_hide && win_state);
    unsigned key = (unsigned)top_zoom | (unsigned)pic_mode << 1 | (unsigned)win_hide << 4 | (unsigned)win_state << 5;
    int bgnew = strip || !cl_ver || key != cl_key || v->pic_gen != cl_pic || v->pal_gen != cl_pal || s3d_frame != cl_fr;
    if (!bgnew && v->char_gen == cl_chr) { cl_top = topimg_gen; return; }      /* only the message strip changed: the picture (and its mask) is as before */
    if (bgnew) {
        vgascale_set_bg(1); top_render_to(m, topbg); vgascale_set_bg(0);
        if (s3d_frame) { if (fr_key != key) { frame_masks(m); fr_key = key; } build_bgx(); }
    }
    cl_fr = s3d_frame;
    int n = 0;
    for (int i = 0; i < 400 * 240; i++) chmask[i] = topimg[i] != topbg[i];
    if (strip) {                                                  /* the message window strip is drawn with the same blit routine, but it is not a character */
        int ys = top_zoom ? 188 : 176;
        for (int x = 0; x < 400; x++) memset(chmask + x * 240, 0, (240 - ys) * sizeof(uint8_t));
        cl_strip = 240 - ys;
    } else cl_strip = 0;
    for (int i = 0; i < 400 * 240; i++) n += chmask[i];
    if (n) {                                                      /* close small holes (character pixels that happen to match the background) */
        morph5(chtmp, chmask, 1, 240, 400, 1); morph5(chmask, chtmp, 240, 400, 240, 1);
        morph5(chtmp, chmask, 1, 240, 400, 0); morph5(chmask, chtmp, 240, 400, 240, 0);
        n = 0; for (int i = 0; i < 400 * 240; i++) n += chmask[i];
    }
    cl_cov = n * 1000 / (400 * 240);
    cl_pic = v->pic_gen; cl_pal = v->pal_gen; cl_chr = v->char_gen; cl_key = key; cl_top = topimg_gen; cl_ver++;
}
static void make_eye_char(uint16_t *dst, int eye, int pop, int fpop, int frame, int chars) {
    int s = eye ? -(pop / 2) : pop - pop / 2;           /* things in front of the screen move right in the left image and left in the right image */
    int fs = eye ? -(fpop / 2) : fpop - fpop / 2;
    const uint16_t *base = frame ? bgx : topbg;
    for (int x = 0; x < 400; x++) {
        uint16_t *dc = dst + x * 240;
        memcpy(dc, base + x * 240, 240 * sizeof(uint16_t));
        if (frame) {                                    /* the picture frame, in front of the picture; past the screen edge it simply continues */
            int sx = x - fs; sx = sx < 0 ? 0 : sx > 399 ? 399 : sx;
            const uint8_t *fm = frmask + sx * 240; const uint16_t *fp = topbg + sx * 240;
            for (int j = 0; j < 240; j++) if (fm[j]) dc[j] = fp[j];
        }
        int sx = x - s;
        if (chars && sx >= 0 && sx <= 399) { const uint16_t *cs = topimg + sx * 240; const uint8_t *cm = chmask + sx * 240; for (int j = 0; j < 240; j++) if (cm[j]) dc[j] = cs[j]; }
        if (cl_strip) memcpy(dc, topimg + x * 240, cl_strip * sizeof(uint16_t));       /* message window: as it is, at the screen surface */
    }
}
/* copies the top picture into the (back) framebuffers, in 2D or as a stereo pair */
static void top_present(Machine *m) {
    if (!s3d_on) { memcpy(fbTop, topimg, sizeof topimg); return; }
    if (s3d_chars && cl_top != topimg_gen) top_render(m);          /* the character layer has to be built from the current picture */
    int key = s3d_tilt | s3d_pop << 8 | s3d_fpop << 16 | s3d_mode << 24;
    if (eye_gen != topimg_gen || eye_key != key || (s3d_chars && eye_cl != cl_ver)) {
        if (s3d_chars) {
            int chars = !(cl_cov < 3 || cl_cov > 700);      /* no character, or a full-screen picture: nothing to lift out */
            if (!chars && !s3d_frame) { memcpy(eyeL, topimg, sizeof eyeL); memcpy(eyeR, topimg, sizeof eyeR); }
            else { make_eye_char(eyeL, 0, s3d_pop, s3d_fpop, s3d_frame, chars); make_eye_char(eyeR, 1, s3d_pop, s3d_fpop, s3d_frame, chars); }
        } else {
            int B = (s3d_tilt + s3d_pop + 1) / 2 + 1;
            make_eye(eyeL, topimg, 0, s3d_tilt, s3d_pop, B);
            make_eye(eyeR, topimg, 1, s3d_tilt, s3d_pop, B);
        }
        eye_gen = topimg_gen; eye_key = key; eye_cl = cl_ver;
    }
    memcpy(fbTop, eyeL, sizeof eyeL); memcpy(fbTopR, eyeR, sizeof eyeR);
}
static uint8_t botrgb[320 * 240 * 3];
static int last_glyphs;

static void bottom_render(Machine *m) {
    last_glyphs = textcap_render(m, botrgb, 320, 240);
    const uint8_t *p = botrgb;
    for (int y = 0; y < 240; y++)
        for (int x = 0; x < 320; x++, p += 3) fbBot[x * 240 + (239 - y)] = C565(p[0], p[1], p[2]);
}

/* ------------------------------------------------------------------ pause menu */
enum { MI_RESUME, MI_TEXT, MI_TOP, MI_WIN, MI_PIC, MI_3D, MI_3DM, MI_CPU, MI_MOUSE, MI_SND, MI_QUIT, MI_COUNT };
static const char *PIC_NAME[] = { "꽉 채움", "늘림", "비율 유지" };
static double stat_speed = 1.0, stat_mips = 0, stat_busy = 0, stat_skip = 0;

static void menu_draw(Machine *m, int sel) {
    const uint16_t fg = C565(235, 235, 235), hi = C565(255, 220, 80), dim = C565(140, 150, 180), bar = C565(44, 52, 96);
    fill(fbBot, 320, C565(10, 10, 30));
    ktext(fbBot, 320, 8, 3, 304, "일시정지", hi, 1);
    char line[96];
    const int step = KF_LH - 1, y0 = 3 + KF_LH + 3;
    int y = y0;
    for (int i = 0; i < MI_COUNT; i++) {
        switch (i) {
        case MI_RESUME: snprintf(line, sizeof line, "계속하기"); break;
        case MI_CPU:
            if (cpu_mode == 0) snprintf(line, sizeof line, "CPU 속도: 자동 (%.1f MIPS)", m->ips / 1e6);
            else snprintf(line, sizeof line, "CPU 속도: %.0f MIPS 고정", CPU_FIXED[cpu_mode] / 1e6);
            break;
        case MI_MOUSE: snprintf(line, sizeof line, "마우스 속도: %d", mouse_level); break;
        case MI_TEXT: snprintf(line, sizeof line, "하단 글자 크기: %s", TEXT_NAME[text_size]); break;
        case MI_TOP: snprintf(line, sizeof line, "상단 화면: %s", top_zoom ? "확대 (꽉 채움)" : "원본 4:3"); break;
        case MI_WIN: snprintf(line, sizeof line, "상단 대화창: %s", win_hide ? "숨김" : "표시"); break;
        case MI_PIC: snprintf(line, sizeof line, "상단 그림 (대화창 없음): %s", PIC_NAME[pic_mode]); break;
        case MI_3D:
            if (s3d_level == 0) snprintf(line, sizeof line, "상단 3D 효과: 끔");
            else if (s3d_slider < 0.03f) snprintf(line, sizeof line, "상단 3D 효과: %s (3D 슬라이더를 올리세요)", S3D_NAME[s3d_level]);
            else snprintf(line, sizeof line, "상단 3D 효과: %s (슬라이더 %d%%)", S3D_NAME[s3d_level], (int)(s3d_slider * 100.f + 0.5f));
            break;
        case MI_3DM: snprintf(line, sizeof line, "상단 3D 방식: %s", s3d_mode == 0 ? "캐릭터+테두리" : s3d_mode == 1 ? "화면 전체(기울임)" : "캐릭터만"); break;
        case MI_SND: snprintf(line, sizeof line, "소리 시험 (음이 납니다)"); break;
        default: snprintf(line, sizeof line, "게임 종료"); break;
        }
        if (i == sel) frect(fbBot, 320, 3, y - 1, 314, step, bar);
        ktext(fbBot, 320, 9, y, 304, line, i == sel ? hi : fg, 0);
        y += step;
    }
    char st[200];
    snprintf(st, sizeof st, "속도 %3.0f%%  CPU %2.0f%%  %.1f MIPS", stat_speed * 100.0, stat_busy * 100.0, stat_mips);
    int tx = 8 + kwidth("일시정지") + 16;                   /* the speed numbers sit to the right of the title (the 3D item made the list one line longer) */
    ktext(fbBot, 320, tx, 3, 312 - tx, st, dim, 0);
    snprintf(st, sizeof st, "소리 끊김 %u회   미처리 %u   글자 캡처 %s", aud_underruns, (unsigned)m->stat_unhandled, textcap_active(m) ? "켜짐" : "꺼짐");
    ktext(fbBot, 320, 8, y + 3, 306, st, dim, 0);
    ktext(fbBot, 320, 8, 240 - KF_LH - 1, 306, "십자키: 선택/변경   A: 확인   B·START: 계속", dim, 0);
}

/* returns 1 to quit */
static int text_changed;
static int pause_menu(Machine *m) {
    int sel = 0;
    if (logfp) fflush(logfp);          /* the pause menu is a good moment for the SD card write */
    input_release_all(m);
    audio_hold();
    while (aptMainLoop()) {
        s3d_update();
        fb_get();
        menu_draw(m, sel);
        /* keep showing the last game frame on top */
        top_present(m);
        present();
        hidScanInput();
        uint32_t d = hidKeysDown();
        if (d & (KEY_START | KEY_B)) { cfg_save(); return 0; }
        if (d & KEY_DDOWN) sel = (sel + 1) % MI_COUNT;
        if (d & KEY_DUP) sel = (sel + MI_COUNT - 1) % MI_COUNT;
        int dir = ((d & KEY_DRIGHT) ? 1 : 0) - ((d & KEY_DLEFT) ? 1 : 0);
        if (sel == MI_CPU && (dir || (d & KEY_A))) {
            cpu_mode = (cpu_mode + (dir ? dir : 1) + N_CPU_MODES) % N_CPU_MODES;
            if (cpu_mode) machine_set_ips(m, CPU_FIXED[cpu_mode]);
        }
        if (sel == MI_MOUSE && (dir || (d & KEY_A))) { mouse_level += dir ? dir : 1; if (mouse_level > 5) mouse_level = 1; if (mouse_level < 1) mouse_level = 5; }
        if (sel == MI_TEXT && (dir || (d & KEY_A))) { text_size = (text_size + (dir ? dir : 1) + 4) % 4; textcap_set_max_scale(TEXT_SCALE[text_size]); text_changed = 1; }
        if (sel == MI_TOP && (dir || (d & KEY_A))) { top_zoom ^= 1; top_clear(); top_render(m); }
        if (sel == MI_WIN && (dir || (d & KEY_A))) { win_hide ^= 1; win_cand = win_state = win_hide && vgascale_window_up(m); win_cnt = 0; top_clear(); top_render(m); }
        if (sel == MI_PIC && (dir || (d & KEY_A))) { pic_mode = (pic_mode + (dir ? dir : 1) + 3) % 3; top_clear(); top_render(m); }
        if (sel == MI_3D && (dir || (d & KEY_A))) s3d_level = (s3d_level + (dir ? dir : 1) + 4) % 4;
        if (sel == MI_3DM && (dir || (d & KEY_A))) s3d_mode = (s3d_mode + (dir ? dir : 1) + 3) % 3;
        if (sel == MI_SND && (d & KEY_A)) { ktext(fbBot, 320, 9, 240 - 2 * KF_LH - 3, 304, "재생 중...", C565(255, 220, 80), 1); present(); audio_test(); }
        if (sel == MI_RESUME && (d & KEY_A)) { cfg_save(); return 0; }
        if (sel == MI_QUIT && (d & KEY_A)) { cfg_save(); return 1; }
    }
    return 1;
}

/* ------------------------------------------------------------------ main */
static int file_exists(const char *dir, const char *name) {
    char p[300]; snprintf(p, sizeof p, "%s/%s", dir, name);
    FILE *f = fopen(p, "rb"); if (!f) return 0; fclose(f); return 1;
}

int main(void) {
    gfxInit(GSP_RGB565_OES, GSP_RGB565_OES, false);
    gfxSet3D(false);
    gfxSetDoubleBuffering(GFX_BOTTOM, false);
    osSetSpeedupEnable(true);
    t_start = svcGetSystemTick();

    const char *gdir = NULL;
    for (int i = 0; GAME_DIRS[i]; i++) if (file_exists(GAME_DIRS[i], "SILV1.COM") || file_exists(GAME_DIRS[i], "silv1.com")) { gdir = GAME_DIRS[i]; break; }
    if (!gdir) {
        message_screen("게임 파일을 찾을 수 없습니다",
            "게임 파일을 SD 카드에 복사해 주세요.\n(SILV1.COM, SILV.EXE, MUSICV.COM,\nSAGWA.*, FLAG*, SILK*.DAT ...)\n\n  sdmc:/3ds/nonomura/\n\n복사한 뒤 앱을 다시 시작하세요.");
        gfxExit(); return 0;
    }
    char logpath[300]; snprintf(logpath, sizeof logpath, "%s/nono_log.txt", gdir);
    logfp = fopen(logpath, "w");
    if (logfp) setvbuf(logfp, NULL, _IOFBF, 16384);
    snprintf(cfg_path, sizeof cfg_path, "%s/nono_cfg.txt", gdir);
    cfg_load();
    textcap_set_max_scale(TEXT_SCALE[text_size]);
    bool is_new = false; APT_CheckNew3DS(&is_new);
    LOG("Nonomura 3DS native v%s  new3ds=%d  gamedir=%s", APP_VERSION, (int)is_new, gdir);

    audio_init();
    LOG("audio %s", audio_ok ? "ok" : "unavailable");

    Machine *m = machine_new(gdir);
    if (!m) { message_screen("메모리 부족", "가상 PC를 만들 메모리가 없습니다."); gfxExit(); return 0; }
    m->verbose = 0;
    m->opl = opl_new(AUD_RATE);
    opl_attach(m->opl, (opl_clock_fn)machine_vtime_ns, m);
    textcap_init(m);
    idle_init(m);
    uint32_t ips = is_new ? 4000000u : 1500000u;
    machine_set_ips(m, ips);

    fb_get(); fill(fbBot, 320, C565(10, 10, 30));
    { const char *lt = "불러오는 중..."; ktext(fbBot, 320, (320 - kwidth(lt) - 2) / 2, 108, 304, lt, C565(230, 230, 230), 1); }
    fill(fbTop, 400, 0); present(); fb_get(); fill(fbTop, 400, 0); present();
    dos_now_ms = now_ms;
    dos_cache_preload(m);              /* the big data files go into RAM: no SD-card stalls (and sound dropouts) while playing */
    LOG("data cached");

    if (dos_exec(m, "MUSICV.COM", "") < 0) { LOG("MUSICV.COM missing"); message_screen("MUSICV.COM 없음", "음악 드라이버 MUSICV.COM 이\n게임 폴더에 있어야 합니다."); goto done; }
    { long total = 0; int guard = 0; while (!m->exited && total < 20000000 && ++guard < 400) total += machine_run(m, 100000);
      LOG("MUSICV done: exited=%d tsr=%d instr=%ld", m->exited, m->tsr_kept, total); }
    if (dos_exec(m, "SILV1.COM", "main.mes D D") < 0) { LOG("SILV1.COM launch failed"); message_screen("SILV1.COM 실행 실패", "SILV1.COM / SILV.EXE 를 시작할 수 없습니다.\n게임 파일이 모두 복사되었는지 확인하세요."); goto done; }
    LOG("game started  top_zoom=%d text_size=%d cpu_mode=%d", top_zoom, text_size, cpu_mode);
    top_clear();

    u64 win_t0 = svcGetSystemTick(), win_busy = 0, win_v0 = machine_vtime_ns(m), win_i0 = m->icount, win_s0 = m->skipped_total;
    int win_frames = 0, frame = 0, lag_frames = 0, bot_force = 1;
    u64 pace_last = svcGetSystemTick(), pace_v0 = machine_vtime_ns(m);
    double pace_clock = 0, pace_total = 0, pace_adj = 0, aq_ema = lead_s + 0.015;   /* pace_clock: virtual seconds earned so far (reduced when a backlog is forgiven); pace_total: same, never reduced */
    u64 prev_f0 = 0; double stat_maxfr = 0, win_maxfr = 0, win_pt0 = 0; unsigned slow100 = 0, slow250 = 0;
    double pt[5] = {0}, worst_pt[5] = {0}, worst_ft = 0, worst_at = 0, other_w = 0; u64 tk;     /* ms spent in: emulation, sound, top picture, bottom screen, vblank wait - for the slowest frame so far */
    double pace_lead = audio_ok ? lead_s : 0, last_lead = lead_s; int calm_secs = 0; unsigned last_under = 0;      /* how far the emulation runs ahead of real time (see LEAD_S) */
    uint32_t last_dirty = ~0u, last_gen = ~0u, bot_dirty = ~0u; int last_bot_frame = -100;
    int quit = 0; u64 t_game0 = svcGetSystemTick();

    while (aptMainLoop() && !quit) {
        u64 f0 = svcGetSystemTick();
        hidScanInput();
        if (hidKeysDown() & KEY_START) {
            if (pause_menu(m)) break;
            pace_lead = audio_ok ? lead_s - (double)audio_queued_frames() / AUD_RATE : 0; if (pace_lead < 0) pace_lead = 0; last_lead = lead_s;   /* sound still queued from before the pause counts as lead */
            bot_force = 1; pace_last = svcGetSystemTick(); pace_clock = 0; pace_adj = 0; aq_ema = lead_s + 0.015; prev_f0 = 0; win_pt0 = pace_total; pace_v0 = machine_vtime_ns(m); win_t0 = svcGetSystemTick(); win_busy = 0; win_v0 = machine_vtime_ns(m); win_i0 = m->icount; win_s0 = m->skipped_total; win_frames = 0;
            continue;
        }
        if (m->exited) break;
        input_frame(m);

        /* Emulate the virtual time that has passed in real life (not a fixed 1/60 s: the screen refreshes at 59.83 Hz and
         * frames sometimes take longer), so game and music run at true speed and the audio never gets ahead or behind.
         * Never spend more than ~75% of a real frame, and forget any backlog beyond 50 ms. */
        if (prev_f0) {                                  /* frame-time statistics (for the SELECT overlay) */
            double ft = (double)(f0 - prev_f0) / TICKS_PER_SEC * 1000.0;
            if (ft > win_maxfr) win_maxfr = ft;
            if (ft > worst_ft) { worst_ft = ft; memcpy(worst_pt, pt, sizeof pt); other_w = ft - (pt[0] + pt[1] + pt[2] + pt[3] + pt[4]); worst_at = (double)(f0 - t_game0) / TICKS_PER_SEC; }
            if (ft > 100.0) slow100++;
            if (ft > 250.0) slow250++;
        }
        prev_f0 = f0;
        double dt = (double)(f0 - pace_last) / TICKS_PER_SEC; pace_last = f0;
        if (dt > 1.0) dt = 1.0;
        pace_clock += dt * (1.0 + pace_adj); pace_total += dt * (1.0 + pace_adj);
        if (lead_s != last_lead) { pace_lead += lead_s - last_lead; if (pace_lead < 0) pace_lead = 0; last_lead = lead_s; }
        double owe = pace_clock + pace_lead - (double)(machine_vtime_ns(m) - pace_v0) / 1e9;
        if (owe > pace_lead + 0.050) { pace_clock -= owe - pace_lead - 0.050; owe = pace_lead + 0.050; }
        if (owe < 0) owe = 0;
        long want = (long)(m->ips * owe), done = 0;
#ifdef STUB_JITTER      /* test builds only: end frames at random points to provoke mid-redraw renders */
        { static unsigned js = 0; if (!js) js = getenv("STUB_SEED") ? (unsigned)atoi(getenv("STUB_SEED")) : 12345u; js = js * 1103515245u + 12345u; want = want * (10 + (js >> 16) % 90) / 100; }
#endif
        u64 deadline = f0 + FRAME_TICKS * 75 / 100;
        while (done < want) {
            long c = want - done; if (c > 12000) c = 12000;
            done += machine_run(m, (int)c);
            if (m->exited) break;
            if (svcGetSystemTick() > deadline) break;
        }
        int lagged = done < want;
        lag_frames = lagged ? lag_frames + 1 : 0;
        tk = svcGetSystemTick(); pt[0] = (double)(tk - f0) * 1000.0 / TICKS_PER_SEC; u64 tk0 = tk;
        audio_pump(m);
        tk = svcGetSystemTick(); pt[1] = (double)(tk - tk0) * 1000.0 / TICKS_PER_SEC; tk0 = tk;
        /* Keep the queued sound at its target: if the DSP clock and the system clock disagree a little, or a hiccup left the queue
         * fuller or emptier than planned, the game is run a hair slower or faster until the queue is back (no pitch change, no dropped sound). */
        if (audio_ok && audio_started) {
            aq_ema += ((double)audio_queued_frames() / AUD_RATE - aq_ema) * (1.0 / 40.0);
            pace_adj = -0.25 * (aq_ema - (lead_s + 0.015));
            if (pace_adj > 0.03) pace_adj = 0.03; else if (pace_adj < -0.03) pace_adj = -0.03;
        } else { pace_adj = 0; aq_ema = lead_s + 0.015; }

        /* top screen: re-render the picture when VRAM / palette changed (every other frame if we are struggling) */
        s3d_update();
        fb_get();
        win_update(m);
        if (win_force || (m->vga.dirty != last_dirty && (!lagged || (frame & 1) == 0))) {
            top_render(m);
            last_dirty = m->vga.dirty; win_force = 0;
        }
        top_present(m);
        tk = svcGetSystemTick(); pt[2] = (double)(tk - tk0) * 1000.0 / TICKS_PER_SEC; tk0 = tk;
        if (hidKeysHeld() & KEY_SELECT) {               /* hold SELECT: live performance numbers (for bug reports) */
            char t[320];
            snprintf(t, sizeof t, "spd %3.0f%% cpu %2.0f%% exec %.1fM\nips %.1fM skip %.0f%% aq %dms lead %d\nunder %u drop %u tc %d\nfrm max %.0fms >100:%u >250:%u adj %+.1f%%\nworst %.0fms @%.0fs: emu %.0f snd %.0f\n  top %.0f bot %.0f vb %.0f etc %.0f\ndos max %.0fms (AH %02X) >50ms:%u",
                     stat_speed * 100.0, stat_busy * 100.0, stat_mips, m->ips / 1e6, stat_skip * 100.0, (int)(audio_queued_frames() * 1000ull / AUD_RATE), (int)(lead_s * 1000), aud_underruns, aud_dropped, textcap_active(m),
                     stat_maxfr, slow100, slow250, pace_adj * 100.0,
                     worst_ft, worst_at, worst_pt[0], worst_pt[1], worst_pt[2], worst_pt[3], worst_pt[4], other_w, dos_io_max_ms, (unsigned)dos_io_max_ah, dos_io_slow);
            gtext(fbTop, 400, 2, 2, 46, t, C565(255, 255, 0), C565(0, 0, 0), 1);
            if (s3d_on) gtext(fbTopR, 400, 2, 2, 46, t, C565(255, 255, 0), C565(0, 0, 0), 1);
        }

        /* bottom screen: large dialogue text (rate limited) */
        uint32_t gen = textcap_gen(m);
        int unsettled = textcap_unsettled(m);
        if (bot_force || ((gen != last_gen || m->vga.dirty != bot_dirty || unsettled) && frame - last_bot_frame >= (gen != last_gen ? 4 : unsettled ? 3 : 8))) {
            bottom_render(m);
            last_gen = gen; bot_dirty = m->vga.dirty; last_bot_frame = frame; bot_force = 0;
        }
        u64 f1 = svcGetSystemTick();
        pt[3] = (double)(f1 - tk0) * 1000.0 / TICKS_PER_SEC;
        win_busy += f1 - f0;
        gfxFlushBuffers(); gfxSwapBuffers(); gspWaitForVBlank();
        pt[4] = (double)(svcGetSystemTick() - f1) * 1000.0 / TICKS_PER_SEC;
        frame++; win_frames++;

        /* once a second: compare virtual time with real time and adapt the emulated CPU speed */
        if (win_frames >= 60) {
            u64 now = svcGetSystemTick();
            double real = (double)(now - win_t0) / TICKS_PER_SEC;
            double virt = (double)(machine_vtime_ns(m) - win_v0) / 1e9;
            double ent = pace_total - win_pt0;                 /* virtual time the pacer has earned (the feedback above may run the game a little slow on purpose) */
            double ratio = ent > 0 ? virt / ent : 1.0;
            stat_maxfr = win_maxfr; win_maxfr = 0; win_pt0 = pace_total;
            double busy = real > 0 ? (double)win_busy / TICKS_PER_SEC / real : 1.0;
            stat_speed = ratio; stat_mips = (double)((m->icount - win_i0) - (m->skipped_total - win_s0)) / real / 1e6;   /* instructions really executed */
            stat_busy = busy;
            stat_skip = (m->icount - win_i0) ? (double)(m->skipped_total - win_s0) / (double)(m->icount - win_i0) : 0;
            audio_set_speed(ratio);
            if (aud_underruns != last_under) { last_under = aud_underruns; calm_secs = 0; }
            else if (++calm_secs >= 30 && lead_s > LEAD_S + 0.001) { lead_s -= 0.02; if (lead_s < LEAD_S) lead_s = LEAD_S; calm_secs = 0; }
            if (cpu_mode == 0) {
                uint32_t n = m->ips;
                static int cooldown;
                if (ratio < 0.97) { double k = ratio < 0.5 ? 0.5 : ratio; n = (uint32_t)(m->ips * k * 0.97); cooldown = 6; m->poll_force = 1; }
                else if (cooldown > 0) cooldown--;
                else if (busy < 0.60 && m->ips < IPS_MAX) n = (uint32_t)(m->ips * 1.06);
                if (n < IPS_MIN) n = IPS_MIN;
                if (n > IPS_MAX) n = IPS_MAX;
                if (n != m->ips) machine_set_ips(m, n);
            }
            static int logn;
            if (logn < 40 || (logn % 10) == 0)
                LOG("speed=%.0f%% busy=%.0f%% maxfr=%.0fms adj=%+.2f%% exec=%.2f MIPS skip=%.0f%% aq=%dms lead=%d under=%u drop=%u ips=%u mouse=%d,%d unhandled=%u glyphs=%d tc=%d pc=%04X:%04X mode=%02X vdirty=%u", ratio * 100, busy * 100, stat_maxfr, pace_adj * 100.0, stat_mips, stat_skip * 100, (int)(audio_queued_frames() * 1000ull / AUD_RATE), (int)(lead_s * 1000), aud_underruns, aud_dropped, m->ips, m->mouse_x, m->mouse_y, (unsigned)m->stat_unhandled, last_glyphs, textcap_active(m), m->cpu.seg[CS], m->cpu.ip, m->vga.bios_mode, (unsigned)m->vga.dirty);
            if (m->con_len) { static int lastcl; if (m->con_len != lastcl) { LOG("console: %s", m->con); lastcl = m->con_len; } }
            logn++;
            win_t0 = now; win_busy = 0; win_v0 = machine_vtime_ns(m); win_i0 = m->icount; win_s0 = m->skipped_total; win_frames = 0;
        }
    }

    if (m->exited && aptMainLoop()) {
        char body[700];
        snprintf(body, sizeof body, "게임 프로그램이 끝났습니다 (종료 코드 %d).\n\n%s%s", m->exit_code,
                 m->con_len ? "마지막 콘솔 출력:\n" : "", m->con_len ? m->con : "");
        LOG("game exited code=%d  console: %s", m->exit_code, m->con);
        message_screen("게임 종료", body);
    }
done:
    LOG("shutdown");
    if (logfp) fclose(logfp);
    if (audio_ok) { ndspChnReset(0); ndspExit(); linearFree(abuf); }
    gfxExit();
    return 0;
}
